    --button-default-bgColor-hover: @surface1;
    --button-default-bgColor-active: @subtext2;
    --button-default-bgColor-selected: @subtext2;
    --button-default-bgColor-disabled: fade(@surface0, 70%);
    --button-default-borderColor-rest: @surface1;
    --button-default-borderColor-hover: @surface1;
    --button-default-borderColor-active: @surface1;
    --button-default-borderColor-disabled: fade(@surface0, 70%);

    #diagram {
      .node rect,
      .node circle,
      .node ellipse,
      .node polygon,
      .node path {
        fill: fade(@accent, 10%);
        stroke: @accent;
      }

      .cluster rect {
        fill: @surface0;
        stroke: @subtext2;
      }

      .label text,
      span,
      p {
        fill: @text;
        color: @text;
      }

      .flowchart-link {
        stroke: @subtext0;
      }
      .marker {
        stroke: @subtext0;
        fill: @subtext0;
      }

      .edgeLabel {
        background-color: @mantle;
        p {
          background-color: @subtext2;
        }
      }
    }

    .octicon {
      fill: var(--color-fg-muted) !important;
    }
  }
}

