    --color-banner-error-text: @base !important;

    --shreddit-color-wordmark: @text;

    reddit-search-large {
      .search-input {
        border-color: @surface0 !important;

        &:focus-within {
          border-color: @subtext0 !important;
        }
      }
    }

    reddit-header-large reddit-search-large::before,
    reddit-header-large reddit-search-large::after {
      background:
        linear-gradient(@base, @base) padding-box,
        linear-gradient(90deg, @surface0, @surface0) border-box;
    }

    #pdp-credit-bar {
      --color-neutral-background: @base;
      --color-neutral-content: @text;
      --color-neutral-content-weak: @subtext0;
      --color-primary-hover: lighten(@accent, 10%);
    }

    reddit-header-large reddit-search-large::before,
    reddit-header-large reddit-search-large::after {
      background:
        linear-gradient(@base, @base) padding-box,
        linear-gradient(90deg, @accent, @accent) border-box;
    }
  }
}
